def load_country_currency_data():
    live_rates = {}
    try:
        req = urllib.request.Request(
            "https://open.er-api.com/v6/latest/AUD",
            headers={"User-Agent": "BudgetWiseAI-App"}
        )
        with urllib.request.urlopen(req, timeout=3) as resp:
            data = json.loads(resp.read().decode('utf-8'))
            if data.get("result") == "success":
                live_rates = data.get("rates", {})
                with open(CACHE_FILE, "w", encoding="utf-8") as f:
                    json.dump(live_rates, f)
    except Exception:
        if os.path.exists(CACHE_FILE):
            try:
                with open(CACHE_FILE, "r", encoding="utf-8") as f:
                    live_rates = json.load(f)
            except Exception:
                live_rates = {}

    country_dict = {}
    for country, (flag, code, symbol, fallback_rate) in WORLD_COUNTRIES.items():
        key_name = f"{country} {flag}"
        rate = live_rates.get(code, fallback_rate)
        country_dict[key_name] = {
            "currency": f"{code} ({symbol})",
            "rate": float(rate)
        }

    return country_dict